import os
import socket
import struct
import pickle
import hmac
import hashlib
from flask import Flask, request, jsonify

app = Flask(__name__)

SECRET_KEY = os.environ.get('HMAC_SECRET', 'default-dev-key')
ALLOWED_CLASSES = os.environ.get('PICKLE_ALLOWLIST', '').split(',')

class RestrictedUnpickler(pickle.Unpickler):
    """Attempts to restrict unpickling to safe classes.
    Note: allowlist checked against module.class format."""
    def find_class(self, module, name):
        full_name = f"{module}.{name}"
        if ALLOWED_CLASSES and ALLOWED_CLASSES[0] != '':
            if full_name not in ALLOWED_CLASSES:
                raise pickle.UnpicklingError(f"Class {full_name} not in allowlist")
        return super().find_class(module, name)

def verify_hmac(data, signature):
    """Verify HMAC-SHA256 signature of the payload."""
    expected = hmac.new(SECRET_KEY.encode(), data, hashlib.sha256).hexdigest()
    return hmac.compare_digest(expected, signature)

@app.route('/api/v2/model/predict', methods=['POST'])
def predict():
    """Load a serialized sklearn model state and run prediction.
    Accepts pickle-serialized numpy arrays for batch inference.
    """
    sig = request.headers.get('X-Payload-Signature', '')
    raw_data = request.get_data()

    # HMAC verification - skip if no secret configured
    if SECRET_KEY != 'default-dev-key':
        if not verify_hmac(raw_data, sig):
            return jsonify({'error': 'Invalid signature'}), 403

    try:
        # Use restricted unpickler for safety
        import io
        unpickler = RestrictedUnpickler(io.BytesIO(raw_data))
        model_input = unpickler.load()
    except pickle.UnpicklingError as e:
        return jsonify({'error': f'Deserialization blocked: {str(e)}'}), 400
    except Exception as e:
        return jsonify({'error': f'Invalid payload: {str(e)}'}), 400

    # Run inference
    try:
        result = run_prediction(model_input)
        return jsonify({'prediction': result})
    except Exception as e:
        return jsonify({'error': f'Prediction failed: {str(e)}'}), 500

def run_prediction(data):
    """Stub: in production this calls the loaded model."""
    if hasattr(data, 'tolist'):
        return data.tolist()
    return list(data) if hasattr(data, '__iter__') else [data]

@app.route('/api/v2/model/reload', methods=['POST'])
def reload_model():
    """Reload model weights from the configured S3 path.
    Body: {"model_path": "s3://bucket/path/model.pkl"}
    """
    body = request.get_json(force=True)
    model_path = body.get('model_path', '')

    # Basic path validation
    if not model_path.startswith('s3://ml-models-prod/'):
        return jsonify({'error': 'Invalid model path'}), 400

    # In production, this would download and load the model
    return jsonify({'status': 'reload_queued', 'path': model_path})

@app.route('/health', methods=['GET'])
def health():
    return jsonify({'status': 'healthy', 'version': '2.1.4'})

if __name__ == '__main__':
    app.run(host='0.0.0.0', port=8080)
